"""Bounded microbenchmarks for PawFlow beta.269; synthetic data only."""
import gzip
import hashlib
import json
import os
import platform
import statistics
import sys
import time
from html.parser import HTMLParser
from pathlib import Path

ROOT = Path('/workspace')
BASE = Path(__file__).resolve().parent
sys.path[:0] = [str(ROOT), str(ROOT / 'tests')]
from tasks.io.serve_chat_ui import render_chat_page, _asset_signature, _CHAT_UI_DIR
from core.segmented_jsonl import SegmentedJsonl
from core._conversation_store_transcript import _CsTranscriptMixin
from core.conversation_event_bus import ConversationEventBus
from core.sse_writer import SSEEvent
from test_webchat_motion_browser import _shell_html, _chromium_executable
from playwright.sync_api import sync_playwright

results = {'environment': {'python': platform.python_version(), 'platform': platform.platform(), 'cpu_count': os.cpu_count()}, 'scope': 'Synthetic isolated relay microbenchmarks, not authenticated end-to-end production or device benchmarks.'}

def measure(fn, repeats=5):
    samples = []
    for _ in range(repeats):
        start = time.perf_counter()
        value = fn()
        samples.append((time.perf_counter() - start) * 1000)
    return {'median_ms': round(statistics.median(samples), 3), 'max_ms': round(max(samples), 3), 'samples_ms': [round(x, 3) for x in samples]}, value

class Assets(HTMLParser):
    def __init__(self):
        super().__init__()
        self.paths = []
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'script' and attrs.get('src'):
            self.paths.append(('script', attrs['src']))
        if tag == 'link' and attrs.get('rel') == 'stylesheet':
            self.paths.append(('css', attrs.get('href', '')))

start = time.perf_counter()
html = render_chat_page()
cold_ms = (time.perf_counter() - start) * 1000
parsed = Assets()
parsed.feed(html)
asset_rows = []
for kind, url in parsed.paths:
    if not url.startswith('/chat/js/'):
        asset_rows.append({'kind': kind, 'url': url, 'external_or_other_route': True})
        continue
    path = _CHAT_UI_DIR / url.split('/chat/js/', 1)[1].split('?', 1)[0]
    data = path.read_bytes()
    asset_rows.append({'kind': kind, 'path': str(path.relative_to(ROOT)), 'bytes': len(data), 'gzip_bytes': len(gzip.compress(data)), 'sha256': hashlib.sha256(data).hexdigest()})
timing, _ = measure(render_chat_page, 20)
sig_timing, sig = measure(_asset_signature, 20)
results['assets'] = {'first_render_ms': round(cold_ms, 3), 'warm_render': timing, 'signature': sig_timing, 'signature_entries': len(sig), 'html_bytes': len(html.encode()), 'html_gzip_bytes': len(gzip.compress(html.encode())), 'files': asset_rows}
print('assets complete', flush=True)

log = SegmentedJsonl(BASE / 'fixture-transcript-v2.jsonl')
total = 12000
payload = 'Synthetic history payload. ' * 40
if not log.exists():
  for first in range(0, total, 1000):
    log.append_dicts({'role': 'assistant', 'msg_id': 'fixture-' + str(i), 'seq': i + 1, 'ts': 1700000000 + i, 'content': payload} for i in range(first, first + 1000))
store = _CsTranscriptMixin()
class Counted:
    def __init__(self, inner):
        self.inner = inner
        self.rows = 0
    def iter_rows_reverse(self):
        for row in self.inner.iter_rows_reverse():
            self.rows += 1
            yield row
storage = []
for offset in (0, 1000, 10000):
    def page(offset=offset):
        counted = Counted(log)
        result = store._read_tail(counted, total, 50, offset)
        assert len(result['messages']) == 50
        return counted.rows
    timing, rows = measure(page)
    storage.append({'offset': offset, 'mode': 'offset', 'rows_decoded': rows, **timing})
    if offset:
        anchor = 'fixture-' + str(total - offset)
        def cursor_page():
            counted = Counted(log)
            resolved = store._offset_after_msg_id(counted, anchor)
            result = store._read_tail(counted, total, 50, resolved)
            assert len(result['messages']) == 50
            return counted.rows
        timing, rows = measure(cursor_page)
        storage.append({'offset': offset, 'mode': 'before_msg_id', 'rows_decoded': rows, **timing})
results['history'] = {'fixture_rows': total, 'content_chars_per_row': len(payload), 'measurements': storage}
print('history complete', flush=True)

bus_rows = []
for conversations in (1, 100, 1000, 5000):
    bus = ConversationEventBus()
    event = SSEEvent('token', {'msg_id': 'fixture', 'text': 'sample'})
    now = time.time()
    bus._buffer = {str(i): [(now, event)] for i in range(conversations)}
    def publish_batch():
        for _ in range(200):
            bus.publish('0', event)
    timing, _ = measure(publish_batch)
    bus_rows.append({'buffered_conversations': conversations, 'events': 200, **timing})
    bus._cleanup_all()
results['event_bus'] = bus_rows
(BASE / 'benchmarks.json').write_text(json.dumps(results, indent=2))
print('bus complete', flush=True)

with sync_playwright() as p:
    browser = p.chromium.launch(executable_path=_chromium_executable(p), headless=True, args=['--no-sandbox'])
    results['environment']['chromium'] = browser.version
    context = browser.new_context(viewport={'width': 1280, 'height': 800})
    page = context.new_page()
    page.set_content(_shell_html(), wait_until='domcontentloaded')
    page.evaluate("""() => {
      window.LOGIN_URL = '';
      window.t = key => key;
      window.handlers = {};
      window.eventSource = {addEventListener: (name, callback) => handlers[name] = callback};
      window.finalizeThinking = () => {};
      window.sourceBadge = () => '';
      window.collapseTechnicalGroups = () => {};
      window.auditStreams = {};
      window.getStream = agent => auditStreams[agent] || (auditStreams[agent] = {text: '', el: null, chunks: []});
      window.addMsg = () => {
        const row = document.createElement('article');
        row.innerHTML = '<span class="msg-content"></span>';
        document.getElementById('messages').appendChild(row);
        return row;
      };
    }""")
    for name in ('state.js', 'messages_markdown.js', 'sse_handlers_a.js'):
        page.add_script_tag(path=str(_CHAT_UI_DIR / name))
    page.evaluate("""() => {
      eventSource = {addEventListener: (name, callback) => handlers[name] = callback};
      window.getStream = agent => auditStreams[agent] || (auditStreams[agent] = {text: '', el: null, chunks: []});
      window.isNearBottom = () => false;
      window.scrollBottom = () => {};
      _sseWireA();
    }""")
    measurements = []
    for chars in (8192, 32768, 65536):
        for batch in (1, 4, 16):
            samples = []
            for repeat in range(3):
                result = page.evaluate("""({chars, batch}) => {
                  document.getElementById('messages').replaceChildren();
                  window.auditStreams = {};
                  const text = 'Some **bold words**, a link https://example.test and plain text. '.repeat(Math.ceil(chars / 60)).slice(0, chars);
                  const samples = [];
                  const handler = handlers.token;
                  let calls = 0;
                  let renderCalls = 0;
                  const render = window.renderMarkdown;
                  window.renderMarkdown = text => {renderCalls++; return render(text);};
                  const started = performance.now();
                  for (let offset = 0; offset < text.length; offset += 64 * batch) {
                    const start = performance.now();
                    handler({data: JSON.stringify({agent_name: 'fixture', msg_id: 'fixture-message', text: text.slice(offset, offset + 64 * batch)})});
                    samples.push(performance.now() - start);
                    calls++;
                  }
                  const elapsed = performance.now() - started;
                  window.renderMarkdown = render;
                  const stream = auditStreams.fixture;
                  return {elapsed_ms: elapsed, max_handler_ms: Math.max(...samples), calls, renderCalls, final_text_matches: stream.text === text, final_html: stream.el.querySelector('.msg-content').innerHTML};
                }""", {'chars': chars, 'batch': batch})
                html_digest = hashlib.sha256(result.pop('final_html').encode()).hexdigest()
                samples.append(result)
            measurements.append({'chars': chars, 'merged_chunks': batch, 'chunk_chars': 64, 'median_ms': round(statistics.median(x['elapsed_ms'] for x in samples), 3), 'max_handler_ms': round(max(x['max_handler_ms'] for x in samples), 3), 'calls': samples[-1]['calls'], 'render_calls': samples[-1]['renderCalls'], 'final_text_matches': all(x['final_text_matches'] for x in samples), 'final_html_sha256': html_digest})
    results['streaming'] = {'scope': 'Real token event handler and Markdown/DOM rendering; badge, turn view, scroll/layout reads and transport replaced by inert scaffolding. Merging is a synthetic comparison, not an implementation or end-to-end FPS claim.', 'measurements': measurements}
    context.close()
    browser.close()
print('browser complete', flush=True)
(BASE / 'benchmarks.json').write_text(json.dumps(results, indent=2))
(BASE / 'benchmarks.status').write_text('0')
print(json.dumps({'assets_local_bytes': sum(row.get('bytes', 0) for row in asset_rows), 'history': storage, 'event_bus': bus_rows, 'streaming': measurements}))
